from collections import Counter
import random, numpy as np

def generated(gi, seed, mode='choices', engine='py'):
    h=len(gi); w=len(gi[0]); cnt=Counter(v for r in gi for v in r); colors=list(cnt); weights=[cnt[c] for c in colors]
    if engine=='py': rng=random.Random(seed)
    elif engine=='np': rng=np.random.default_rng(seed)
    elif engine=='rs': rng=np.random.RandomState(seed)
    if mode=='choices':
        if engine=='py': vals=rng.choices(colors,weights=weights,k=4*h*w)
        elif engine=='np': vals=rng.choice(colors,size=4*h*w,p=np.array(weights)/sum(weights)).tolist()
        else: vals=rng.choice(colors,size=4*h*w,p=np.array(weights)/sum(weights)).tolist()
    elif mode=='cell':
        flat=sum(gi,[])
        if engine=='py': vals=[rng.choice(flat) for _ in range(4*h*w)]
        else: vals=rng.choice(flat,size=4*h*w).tolist()
    out=[vals[r*2*w:(r+1)*2*w] for r in range(2*h)]
    for r in range(h): out[r][:w]=gi[r]
    return out

