import zlib, hashlib

def seed_features(g):
 flat=sum(g,[]); key=tuple(tuple(r) for r in g)
 return {
  'sum':sum(flat), 'first':flat[0], 'last':flat[-1], 'n':len(g),
  'weighted':sum((i+1)*v for i,v in enumerate(flat)),
  'squares':sum(v*v for v in flat),
  'hash_tuple':hash(key), 'hash_listrepr':hash(repr(g)),
  'crc32':zlib.crc32(repr(g).encode()),
  'sha32':int.from_bytes(hashlib.sha256(repr(g).encode()).digest()[:4],'big'),
  'sum_mod':sum(flat)%1000003,
 }
